def minPath(grid, k):
    n = len(grid)
    val = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                neighbors = []
                if i > 0:
                    neighbors.append(grid[i-1][j])
                if i < n - 1:
                    neighbors.append(grid[i+1][j])
                if j > 0:
                    neighbors.append(grid[i][j-1])
                if j < n - 1:
                    neighbors.append(grid[i][j+1])
                if neighbors:
                    cur_min = min(neighbors)
                    if val is None or cur_min < val:
                        val = cur_min
    if val is None:
        val = 0
    ans = []
    for i in range(k):
        ans.append(1 if i % 2 == 0 else val)
    return ans
